import numpy as np

def feature(current, candidates, tour, start):
    """Distance from each candidate to the start city, active only when k <= 2 (last two decisions), else zeros."""
    candidates = np.asarray(candidates, dtype=float)
    start = np.asarray(start, dtype=float)
    k = candidates.shape[0]
    d_start = np.linalg.norm(candidates - start[None, :], axis=1)
    if k <= 2:
        m = float(np.max(d_start)) if d_start.size else 0.0
        if m < 1e-12:
            return np.zeros(k, dtype=float)
        return d_start / m
    return np.zeros(k, dtype=float)

import numpy as np

def feature(current, candidates, tour, start):
    """Tangency of each leg cur->candidate to the remaining cloud: |sum of side-signs of all other unvisited cities| / (k-1)."""
    k = candidates.shape[0]
    if k < 2:
        return np.zeros(k)
    dx = candidates[:, 0] - current[0]
    dy = candidates[:, 1] - current[1]
    # cross[i, j] = h_i x h_j = dx_i*dy_j - dy_i*dx_j
    cross = dx[:, None] * dy[None, :] - dy[:, None] * dx[None, :]
    s = np.sign(cross)                      # diagonal is 0, so summing all j == summing j != i
    total = np.abs(s.sum(axis=1))
    return total / (k - 1)
